import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="CÓDIGO ICTUS"; N=7; O="#F28C00"   # franja naranja: tiempo-dependiente
KW=dict(strip=O)
pg=lambda *a,**k: page(*a,**KW,**k)
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("CÓDIGO ICTUS",170,nowrap=True)+big(f'¿SE DESPERTÓ ASÍ? <span style="color:{R}">PUEDE QUEDAR VENTANA</span>',104)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Activación, tiempos, presión arterial, trombólisis y trombectomía. Con ficha final.</div>',cover=True,**KW),
pg(2,N,T,kicker("CUÁNDO ACTIVAR")+big("DÉFICIT AGUDO",150,R,True)+'<div style="font-size:50px;font-weight:800;line-height:1.2">De menos de 24 h o de hora de inicio desconocida</div>'+rows(line("No hay límite de edad ni de escala fijado: solo excluyen la gran dependencia previa o una enfermedad grave e irreversible"),line("Escala RACE ≥ 5: sospecha de oclusión de gran vaso, piensa en trombectomía",True))+note("La hora que cuenta es la última vez que se le vio bien, no la hora en que lo encontraron.")),
pg(3,N,T,kicker("LOS PRIMEROS MINUTOS")+big("GLUCEMIA ANTES",140,R,True)+rows(row("Glucemia capilar","Descarta hipoglucemia; trata si &lt; 60 mg/dl"),row("Hora","Última vez visto bien"),row("Imagen","&lt; 15 min desde la llegada"),row("Puerta-aguja","Mediana de 30 min"))+note("No esperes la coagulación ni las plaquetas para empezar la trombólisis, salvo que sospeches anticoagulación o trombopenia.")),
pg(4,N,T,kicker("MENOS DE 4,5 H")+big("TROMBÓLISIS",170,R,True)+rows(row("Tenecteplasa","0,25 mg/kg en bolo único (máx. 25 mg)"),row("Alteplasa","0,9 mg/kg (máx. 90 mg): 10 % en bolo en 1 min y el resto en 60 min"))+f'<div style="border-top:4px solid {K};padding-top:20px;font-size:38px;font-weight:800;line-height:1.3;color:{R}">No trombolices si: INR &gt; 1,7 · anticoagulante oral directo en las últimas 48 h · plaquetas &lt; 100.000 conocidas · glucemia &lt; 50 mg/dl</div>'+note("Con anticoagulante directo hay excepciones si se dispone de niveles específicos: consúltalas con Neurología.")),
pg(5,N,T,kicker("PRESIÓN ARTERIAL")+big("185 / 110",210,R,True)+'<div style="font-size:48px;font-weight:800;line-height:1.2">Por debajo antes de la trombólisis</div>'+rows(row("24 h después","&lt; 180/105"),row("Sin reperfusión","No la bajes salvo ≥ 220/120"),row("Fármaco","Labetalol o urapidilo IV"),row("Labetalol","50 mg en ≥ 1 min; repetir cada 5 min, máx. 200 mg"))+note("Bajar la sistólica de 140 tras la trombólisis no aporta beneficio.")),
pg(6,N,T,kicker("GRAN VASO Y VENTANA AMPLIADA")+big("TROMBECTOMÍA",148,R,True)+rows(row("Hasta 6 h","Oclusión de gran vaso"),row("De 6 a 24 h","Con selección por imagen"),line("La trombólisis no debe retrasar la trombectomía: no esperes a ver si responde",True),line("Despertar u hora desconocida: con RM (discordancia DWI-FLAIR) o perfusión, la trombólisis es posible hasta 9 h"))),
page(7,N,T,ficha_body("CÓDIGO ICTUS","Adulto",[("ACTIVAR","Déficit agudo &lt; 24 h o de inicio desconocido. RACE ≥ 5: gran vaso"),("1.º","Glucemia capilar. Última vez visto bien. Imagen en &lt; 15 min",True),("TROMBÓLISIS","&lt; 4,5 h. Tenecteplasa 0,25 mg/kg bolo (máx. 25 mg) o alteplasa 0,9 mg/kg (máx. 90 mg; 10 % en bolo)",True),("NO SI","INR &gt; 1,7 · ACOD &lt; 48 h · plaquetas &lt; 100.000 · glucemia &lt; 50"),("PA","&lt; 185/110 antes y &lt; 180/105 24 h. Sin reperfusión, solo si ≥ 220/120"),("TROMBECTOMÍA","Gran vaso: hasta 6 h; 6–24 h con imagen. Sin esperar a la trombólisis",True),("CUIDADOS","O2 si SatO2 &lt; 95 %. Antitérmico si &gt; 37,5 °C. Disfagia antes de nada oral")],"Estrategia en Ictus del SNS 2024; ESO 2021 y 2023 (trombólisis y tenecteplasa); ESO-ESMINT 2019; AHA/ASA 2026",size=128,fs=28),ficha="11",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","codigo-ictus")
